  // spellchecker: ignore-next-line
  admin shopping_mall_admin? @relation(fields: [shopping_mall_admin_id], references: [id], onDelete: Cascade, map: "shopping_mall_email_verification_tokens_shopping_mall__ac1f4b8b")

