  tracking_url String @db.VarChar(80000)

  /// Carrier name matching the shipping record (e.g., 'FedEx', 'UPS', 'DHL').
  /// Must be consistent with order_shippings.carrier.
  carrier String

  /// Timestamp when tracking number was added to the system.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  orderShipping order_shippings @relation(fields: [order_shipping_id], references: [id], onDelete: Cascade)

  @@unique([order_shipping_id])
  @@unique([tracking_number])
  @@index([carrier])
}

